export const FACE_CUTS_BY_GENDER: Record<Gender, FaceCut[]> = {
  woman: WOMAN_FACE_CUTS,
  man: MAN_FACE_CUTS,
  nonbinary: NONBINARY_FACE_CUTS,
};

export function faceCutsFor(gender: Gender): FaceCut[] {
  return FACE_CUTS_BY_GENDER[gender];
}

export function getFaceCut(gender: Gender, id: string): FaceCut | undefined {
  return faceCutsFor(gender).find((f) => f.id === id);
}

export function defaultFaceCutId(gender: Gender): string {
  return faceCutsFor(gender)[0]?.id ?? "";
}

export function randomFaceCutId(gender: Gender, avoidId?: string): string {
  const list = faceCutsFor(gender);
  if (!list.length) return "";
  let pick = list[Math.floor(Math.random() * list.length)]!;
  if (avoidId && list.length > 1) {
    let guard = 0;
    while (pick.id === avoidId && guard++ < 12) {
      pick = list[Math.floor(Math.random() * list.length)]!;
    }
  }
  return pick.id;
}

